export function icon(name, size = 18) {
  const markup = (shapes[name] || []).map(([tag, attrs]) => "<" + tag + " " + Object.entries(attrs).map(([key, value]) => key + '="' + value + '"').join(" ") + "></" + tag + ">").join("");
  return '<svg aria-hidden="true" width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">' + markup + "</svg>";
}
